import { block } from "./bank-utils.mjs";
const cases = [];
const add = (topic, passage, tasks) => cases.push(block(topic, `Situação experimental fictícia:\n${passage}`, tasks));
add("Densidade e flutuação", "Um laboratório mede a massa de 240 g e o volume de 300 cm³ de um objeto homogêneo. Ele é colocado primeiro em água (densidade 1,0 g/cm³) e depois em um líquido de densidade 0,6 g/cm³. Considere que o objeto não absorve líquido, não se dissolve e flutua em equilíbrio quando sua densidade é menor que a do líquido.", [
 ["Qual previsão combina corretamente a medida de densidade e o comportamento nos dois líquidos?", "A densidade é 0,8 g/cm³; flutua na água e afunda no segundo líquido.", ["A densidade é 1,25 g/cm³; afunda nos dois líquidos.", "A densidade é 0,8 g/cm³; afunda na água e flutua no segundo.", "A densidade é 0,6 g/cm³; fica suspenso nos dois líquidos.", "A densidade é 0,8 g/cm³; flutua nos dois líquidos."], "Dividindo massa por volume: 240/300 = 0,8. É menor que 1,0 e maior que 0,6, portanto os comportamentos previstos são diferentes."],
 ["Na água, que volume precisa ficar submerso para que a massa de água deslocada iguale os 240 g do objeto?", "240 cm³", ["300 cm³", "60 cm³", "180 cm³", "400 cm³"], "Na flutuação, a massa de água deslocada deve equilibrar a massa do objeto. Como a água tem 1 g/cm³, o volume deslocado é 240 cm³, 80% do volume do objeto."],
 ["Um segundo objeto do mesmo material tem 600 cm³. Qual massa e comportamento na água são coerentes com a homogeneidade do material?", "480 g e flutuação", ["240 g e suspensão", "750 g e afundamento", "600 g e suspensão", "360 g e afundamento"], "A densidade permanece 0,8 g/cm³; com 600 cm³, a massa é 480 g. O aumento de tamanho não muda a comparação entre as densidades, portanto continua flutuando."],
 ["Uma cavidade fechada reduz a massa do objeto para 180 g, mantendo o volume externo de 300 cm³. No segundo líquido, qual previsão decorre do modelo?", "A densidade média passa a 0,6 g/cm³, igual à do líquido, permitindo suspensão ideal.", ["A densidade média aumenta para 1,67 g/cm³ e o objeto afunda.", "A cavidade não altera a densidade média do objeto.", "A massa menor obriga o objeto a flutuar acima de todo líquido.", "O objeto passa a deslocar sempre 300 g, em qualquer líquido."], "A densidade média é 180/300 = 0,6 g/cm³. Sob as hipóteses ideais, a igualdade das densidades permite equilíbrio totalmente submerso, sem concluir que emerge."],
 ["Para testar a influência da densidade do líquido, qual procedimento controla melhor as demais características do objeto?", "Usar o mesmo objeto intacto em líquidos de densidades conhecidas, mantendo condições comparáveis.", ["Comparar objetos de materiais e tamanhos diferentes em líquidos desconhecidos.", "Aquecer só um dos objetos e mudar também o líquido.", "Alterar a massa e o volume do objeto a cada observação.", "Comparar apenas a massa dos líquidos sem medir seus volumes."], "A comparação isola a mudança no líquido ao manter o objeto e suas propriedades. Variar simultaneamente materiais, volumes ou temperaturas impediria atribuir diferenças à densidade do líquido."],
]);
add("Separação de misturas e conservação", "Uma amostra contém 20 g de areia seca e 30 g de sal completamente dissolvido em 150 g de água. A areia é insolúvel; o sal não é volátil nas condições do experimento. Após filtração ideal, o líquido é dividido em duas partes iguais: uma sofre evaporação até secar; a outra, destilação com coleta completa da água.", [
 ["Qual sequência recupera areia, sal e água sem confundir filtração com remoção de substância dissolvida?", "A filtração retém a areia; a destilação do filtrado separa água e sal.", ["A filtração retém areia e todo o sal, deixando apenas água.", "A evaporação transforma o sal dissolvido em vapor coletável.", "A decantação da areia remove também todo o sal dissolvido.", "A destilação exige que areia e sal tenham a mesma solubilidade."], "A areia é retida pelo filtro, enquanto água e sal dissolvido atravessam. A destilação vaporiza e condensa água, deixando o sal não volátil no recipiente."],
 ["Qual massa de sal resta na metade do filtrado que foi evaporada até secar?", "15 g", ["30 g", "20 g", "75 g", "90 g"], "O filtrado é homogêneo e contém 30 g de sal. Sua divisão em partes iguais distribui 15 g de sal a cada parte; retirar água não elimina esse sal."],
 ["Na metade submetida à destilação, qual massa de água pode ser recuperada sob coleta ideal?", "75 g", ["90 g", "150 g", "15 g", "100 g"], "Os 150 g de água foram repartidos igualmente, resultando em 75 g por metade. A coleta ideal recupera essa água, separada dos 15 g de sal."],
 ["Se o líquido destilado continuar contendo sal, qual hipótese explica uma falha sem contradizer a informação de que o sal não é volátil?", "Gotículas da solução foram arrastadas para o condensador.", ["O sal se tornou água devido ao aquecimento.", "A insolubilidade da areia provocou volatilização do sal.", "O filtro transformou a solução em sal gasoso.", "A conservação de massa obriga o sal a acompanhar todo vapor de água."], "O transporte mecânico de gotículas pode contaminar o destilado sem que o sal vaporize. O experimento ideal exclui esse arraste; a observação indicaria falha no procedimento."],
 ["Qual massa total permite verificar a recuperação completa dos três componentes antes de dividir o filtrado?", "200 g", ["180 g", "170 g", "50 g", "150 g"], "A massa inicial é 20 + 30 + 150 = 200 g. Sem perdas, a soma das massas recuperadas deve conservar esse total; areia e sal não deixam de contar por serem separados."],
]);
add("Energia elétrica e eficiência", "Uma bomba recebe 600 W de potência elétrica durante 10 minutos. Sua eficiência de conversão em energia útil é 70%; o restante aquece o equipamento e o ambiente. Uma segunda bomba recebe 500 W, tem eficiência de 84% e realiza a mesma transferência de água nas condições consideradas.", [
 ["Comparando a potência útil das duas bombas, qual conclusão é correta?", "As duas fornecem 420 W úteis, embora a segunda demande menos potência elétrica.", ["A primeira fornece 600 W úteis e a segunda 500 W.", "A segunda fornece 84 W úteis, independentemente da potência recebida.", "A primeira é mais eficiente por receber maior potência.", "As duas dissipam a mesma potência, pois a potência útil é igual."], "A primeira fornece 600 × 0,70 = 420 W. A segunda fornece 500 × 0,84 = 420 W. Suas dissipações são 180 W e 80 W, respectivamente."],
 ["Que energia útil a primeira bomba fornece nos dez minutos, em joules?", "252.000 J", ["360.000 J", "42.000 J", "108.000 J", "4.200 J"], "Dez minutos correspondem a 600 segundos. Multiplicando a potência útil de 420 J/s pelo tempo, obtém-se 252.000 J; usar os 600 W daria energia elétrica recebida."],
 ["Qual energia a primeira bomba dissipa no mesmo intervalo?", "108.000 J", ["252.000 J", "180 J", "360.000 J", "18.000 J"], "A potência dissipada é 30% de 600 W, ou 180 W. Durante 600 s, isso representa 108.000 J, completando os 360.000 J recebidos."],
 ["Uma fonte fornece apenas 500 W. Qual bomba pode manter os 420 W úteis nas condições descritas?", "A segunda; sua eficiência compensa a menor potência elétrica disponível.", ["A primeira, porque 70% de 500 W corresponde a 420 W.", "As duas, pois eficiência não afeta a potência útil.", "Nenhuma, porque a energia dissipada precisa ser igual à útil.", "A primeira, porque sua potência nominal é maior que a disponível."], "Na fonte de 500 W, a primeira produziria 350 W úteis se a eficiência se mantivesse. A segunda fornece 500 × 0,84 = 420 W, dentro da condição apresentada."],
 ["Qual interpretação respeita conservação de energia e eficiência?", "A energia não convertida em trabalho útil é transferida como outras formas, principalmente calor.", ["Os 30% não úteis deixam de existir durante o funcionamento.", "A eficiência de 84% significa criação de energia pela segunda bomba.", "A potência útil pode superar a recebida se o intervalo for suficientemente longo.", "A dissipação térmica só ocorre quando a eficiência é zero."], "Eficiência descreve a fração aproveitada para a finalidade considerada. As perdas úteis não são desaparecimento de energia: há transferência para calor e outras formas."],
]);
add("Circuitos e associação de resistores", "Dois resistores ideais de 6 Ω são ligados a uma fonte ideal de 12 V. No circuito I ficam em série; no II, em paralelo. Use U = R × I e P = U × I. Considere fios sem resistência, resistores ôhmicos e ausência de limite de corrente na fonte.", [
 ["Qual comparação das correntes totais está correta?", "1 A no circuito I e 4 A no circuito II.", ["2 A em ambos os circuitos.", "4 A no circuito I e 1 A no II.", "1 A em I e 2 A em II.", "12 A em I e 6 A em II."], "Em série, a resistência total é 12 Ω e a corrente 12/12 = 1 A. Em paralelo, a resistência equivalente é 3 Ω e a corrente total 12/3 = 4 A."],
 ["Qual diferença de potencial aparece em cada resistor em série?", "6 V", ["12 V", "3 V", "24 V", "1 V"], "A corrente de 1 A atravessa cada resistor de 6 Ω. Pela relação U = RI, cada queda é 6 V; as duas somam os 12 V da fonte."],
 ["Qual potência total é dissipada no circuito em paralelo?", "48 W", ["12 W", "24 W", "6 W", "144 W"], "A fonte fornece 12 V com corrente total 4 A, logo P = 12 × 4 = 48 W. Cada ramo recebe 12 V e dissipa 24 W."],
 ["Se um resistor é retirado de cada circuito, deixando os fios restantes sem criar atalhos, qual mudança descreve o resultado?", "Em série o circuito fica aberto; em paralelo o outro ramo continua conduzindo.", ["Os dois circuitos continuam com suas correntes anteriores.", "Em série a corrente dobra; em paralelo o circuito inteiro abre.", "Os dois passam a ter resistência equivalente nula.", "Em paralelo a tensão do ramo restante cai obrigatoriamente para 6 V."], "Na série, remover um componente interrompe o único caminho. No paralelo, permanece um caminho fechado pelo resistor do outro ramo, ainda ligado aos 12 V ideais."],
 ["Qual conclusão depende explicitamente da hipótese de fonte ideal adotada?", "A tensão permanece 12 V mesmo quando o paralelo exige maior corrente total.", ["A corrente nos dois ramos paralelos tem valores diferentes apesar de resistores iguais.", "A resistência dos resistores desaparece em paralelo.", "A potência dissipada independe da tensão aplicada.", "O circuito em série exige mais corrente que o paralelo."], "A fonte ideal mantém a tensão especificada sem limite de corrente. Fontes reais podem ter resistência interna e limitações, não consideradas neste modelo."],
]);
add("Temperatura e equilíbrio térmico", "Em um recipiente isolado, misturam-se 200 g de água a 60 °C com 400 g de água a 15 °C. Não há mudança de fase nem troca de calor com o recipiente ou ambiente. Ambas as porções têm o mesmo calor específico; o calor perdido pela parte quente iguala o recebido pela parte fria.", [
 ["Qual temperatura final satisfaz o equilíbrio de energia?", "30 °C", ["37,5 °C", "45 °C", "22,5 °C", "75 °C"], "Como o calor específico é igual, usa-se a média ponderada pelas massas: (200 × 60 + 400 × 15)/600 = 30 °C. A média simples ignoraria a porção fria maior."],
 ["Se as duas massas fossem iguais, mantendo as temperaturas iniciais, qual seria a temperatura final ideal?", "37,5 °C", ["30 °C", "60 °C", "15 °C", "45 °C"], "Com massas iguais e mesmo calor específico, as capacidades térmicas são iguais. A temperatura final é (60 + 15)/2 = 37,5 °C, diferente do primeiro experimento."],
 ["Mantendo 200 g de água quente, que massa de água a 15 °C produziria temperatura final de 45 °C?", "100 g", ["200 g", "400 g", "50 g", "600 g"], "A água quente perde proporcionalmente 200 × (60 − 45) = 3.000 unidades de mΔT. A fria recebe m × (45 − 15); portanto 30m = 3.000 e m = 100 g."],
 ["Uma medida de 12 °C após a mistura inicial é compatível com quais condições?", "Indica que alguma hipótese do modelo falhou, pois está abaixo das duas temperaturas iniciais.", ["É o equilíbrio esperado quando a água fria tem maior massa.", "Comprova que a água quente transferiu temperatura, sem transferir energia.", "É prevista pela média ponderada das massas do enunciado.", "Resulta obrigatoriamente de misturar volumes diferentes, mesmo com isolamento."], "Sem troca externa nem mudança de fase, o equilíbrio deve estar entre 15 e 60 °C. Um valor de 12 °C exige investigar medição, perdas ou outra condição não prevista."],
 ["Se o recipiente inicialmente frio absorvesse calor, mantendo o restante comparável, o que se esperaria em relação aos 30 °C calculados?", "Temperatura final menor que 30 °C, pois parte da energia aqueceria o recipiente.", ["Temperatura maior, porque absorção de calor aumenta a energia disponível para a água.", "Temperatura necessariamente igual a 60 °C.", "Nenhuma diferença, independentemente da capacidade térmica do recipiente.", "Temperatura menor que 15 °C obrigatoriamente."], "Um recipiente frio com capacidade térmica recebe energia da mistura. A hipótese de não aquecê-lo foi usada no cálculo; sua inclusão reduz a temperatura final em relação aos 30 °C ideais."],
]);
add("Fotossíntese e controle experimental", "Quatro ramos da mesma espécie aquática são mantidos em frascos com igual volume de água, temperatura e concentração inicial de gás carbônico. A recebe luz intensa; B, luz moderada; C, luz intensa com gás carbônico reduzido; D fica no escuro. Em uma hora, produzem respectivamente 40, 20, 12 e 0 bolhas observáveis. As bolhas são usadas apenas como indicador aproximado de liberação de oxigênio.", [
 ["Que comparação permite avaliar o efeito da intensidade luminosa mantendo as outras condições descritas?", "A e B", ["A e C", "C e D", "B e C", "Somente D"], "A e B diferem na intensidade da luz, mas mantêm as condições iniciais comparáveis. A e C variam gás carbônico; outras comparações alteram mais de uma variável."],
 ["Que interpretação é sustentada pela comparação entre A e C?", "Mesmo com luz intensa, a redução de gás carbônico pode limitar a liberação de oxigênio.", ["A luz intensa elimina qualquer influência da disponibilidade de gás carbônico.", "O oxigênio produzido demonstra que o gás carbônico é dispensável ao processo.", "A redução de gás carbônico aumenta a produção observada de bolhas.", "A e C receberam necessariamente temperaturas diferentes."], "A intensidade luminosa foi mantida, mas C recebeu menos gás carbônico e produziu menos bolhas. Isso é compatível com limitação por disponibilidade de reagente, sem provar sozinho todos os mecanismos."],
 ["A ausência de bolhas em D permite concluir o quê, sem extrapolar o indicador?", "Não foi observada liberação de oxigênio como a dos frascos iluminados; não se prova ausência de respiração.", ["A planta interrompeu obrigatoriamente toda atividade celular.", "A respiração só ocorre quando há luz intensa.", "O frasco D demonstra que plantas não consomem oxigênio.", "No escuro a planta passou necessariamente a produzir mais glicose."], "Fotossíntese e respiração são processos diferentes. Ausência de bolhas observáveis não comprova ausência de respiração ou de outras atividades celulares."],
 ["Qual razão entre as contagens de A e B resume o resultado, sem afirmar precisão sobre a massa de oxigênio?", "2 para 1", ["1 para 2", "4 para 1", "3 para 2", "5 para 2"], "As contagens são 40 e 20, portanto 40/20 = 2. Bolhas podem ter tamanhos diferentes; a razão entre contagens não prova, por si só, a mesma razão entre massas de oxigênio."],
 ["Como melhorar a confiabilidade da conclusão sobre intensidade luminosa?", "Repetir A e B com réplicas e medir volume de gás, mantendo as condições comparáveis.", ["Alterar simultaneamente luz, temperatura e tamanho dos ramos.", "Usar espécies diferentes em A e B sem registrar a diferença.", "Excluir B porque seu resultado foi menor.", "Substituir as contagens por uma opinião sobre aparência das plantas."], "Réplicas ajudam a estimar variação; medir volume supera parte da limitação de contar bolhas. Controlar as demais condições mantém a interpretação da variável estudada."],
]);
add("Fluxo de energia e cadeias alimentares", "Em uma cadeia simplificada, produtores armazenam 80.000 kJ disponíveis em um período. Considere que 10% da energia de cada nível se torna disponível ao nível seguinte. A cadeia é: plantas → herbívoros → pequenos predadores → predador final. O modelo trata fluxo de energia, não reciclagem de átomos.", [
 ["Que energia fica disponível ao predador final no modelo?", "80 kJ", ["800 kJ", "8.000 kJ", "8 kJ", "24.000 kJ"], "São três transferências: 80.000 × 0,1 = 8.000; depois 800; depois 80 kJ. Não se aplica 10% uma única vez a toda a cadeia."],
 ["Se o consumo humano ocorrer diretamente no nível dos herbívoros em vez do predador final, qual comparação de energia entre esses níveis decorre do modelo?", "O nível dos herbívoros dispõe de cem vezes a energia do predador final.", ["Os herbívoros dispõem de dez vezes menos energia.", "Os níveis dispõem da mesma energia porque os átomos são reciclados.", "O predador final dispõe de cem vezes mais energia.", "A diferença é apenas de 10% da energia inicial."], "Herbívoros têm 8.000 kJ e o predador final 80 kJ. A razão é 8.000/80 = 100, resultante das duas transferências intermediárias."],
 ["O que acontece com a energia que não chega ao nível seguinte?", "Parte é usada em processos vitais e dissipada como calor; parte permanece em material não consumido.", ["Ela é integralmente criada novamente pelos decompositores.", "Ela deixa de existir quando um organismo respira.", "Ela se acumula inteira no predador final.", "Ela retorna obrigatoriamente aos produtores na mesma forma aproveitável."], "A eficiência de transferência não significa destruição de energia. Há metabolismo, dissipação de calor e material não ingerido ou assimilado; matéria e energia têm trajetórias distintas."],
 ["Se a energia inicialmente armazenada cair para 40.000 kJ, mantendo as eficiências, qual é a nova disponibilidade ao predador final?", "40 kJ", ["400 kJ", "4.000 kJ", "80 kJ", "4 kJ"], "Reduzir pela metade a energia dos produtores reduz pela metade cada nível sob o mesmo modelo. Três fatores de 0,1 levam de 40.000 a 40 kJ."],
 ["Que afirmação distingue corretamente decomposição de fluxo energético?", "Decompositores devolvem nutrientes ao ambiente, mas não reciclam toda a energia dissipada como calor.", ["Decompositores tornam a cadeia independente de entrada de energia.", "Reciclagem de nutrientes implica retorno integral de energia útil às plantas.", "A atuação dos decompositores aumenta obrigatoriamente a eficiência de todos os níveis para 100%.", "A decomposição só ocorre na presença do predador final."], "Nutrientes podem ser reutilizados pelos produtores. A energia dissipada não retorna integralmente em forma aproveitável; ecossistemas dependem de entrada energética, geralmente solar."],
]);
add("Genética e probabilidade", "Em uma característica hipotética de um organismo diploide, o alelo A é dominante e a é recessivo. A característica recessiva aparece apenas em aa. Dois indivíduos Aa produzem descendentes, com segregação independente dos gametas e sem diferença de viabilidade entre genótipos. O modelo não pretende explicar toda a herança humana.", [
 ["Qual probabilidade de um descendente apresentar a característica recessiva?", "25%", ["50%", "75%", "100%", "12,5%"], "Cada indivíduo fornece A ou a com probabilidade 1/2. O genótipo aa depende de a de ambos: 1/2 × 1/2 = 1/4, ou 25%."],
 ["Entre os descendentes que não apresentam a característica recessiva, que fração esperada é heterozigota?", "2/3", ["1/2", "1/4", "3/4", "1/3"], "As proporções são 1 AA, 2 Aa e 1 aa. Ao excluir aa, restam três partes, duas delas Aa. A probabilidade condicionada é 2/3, não 1/2."],
 ["Qual chance de dois descendentes independentes serem ambos aa?", "6,25%", ["25%", "50%", "12,5%", "75%"], "Cada descendente tem chance 1/4. Para dois resultados independentes, multiplica-se 1/4 × 1/4 = 1/16 = 6,25%. Não se somam probabilidades para a ocorrência conjunta."],
 ["O nascimento de um descendente aa altera a probabilidade de aa no próximo nascimento sob as hipóteses dadas?", "Não; permanece 25%, pois os resultados são independentes no modelo.", ["Sim; passa a zero porque a cota recessiva já foi cumprida.", "Sim; aumenta para 50% porque o primeiro confirmou o alelo.", "Sim; torna-se 100% porque ambos os pais fornecem apenas a.", "Não; permanece 75%, a probabilidade inicial de aa."], "O primeiro resultado não modifica os gametas possíveis dos pais Aa. A proporção esperada não é uma cota que precisa ser compensada em cada família."],
 ["Um indivíduo aa cruza com outro AA. Que resultado se espera quanto ao genótipo dos descendentes?", "Todos Aa, sem manifestação recessiva sob a dominância especificada.", ["Metade AA e metade aa.", "Todos aa, com manifestação recessiva.", "Um quarto AA, metade Aa e um quarto aa.", "Todos AA, pois o alelo dominante elimina a."], "O indivíduo aa só fornece a e o AA só fornece A; todos os descendentes recebem Aa. Dominância trata manifestação, não eliminação do alelo recessivo."],
]);
add("Seleção de resistência bacteriana", "Uma população bacteriana inclui variantes hereditárias: 99% são sensíveis a uma substância experimental e 1% são resistentes. Sob exposição, sobrevivem 1% das sensíveis e 90% das resistentes. A substância não cria a variante resistente no modelo; todas as sobreviventes podem se reproduzir. Considere população inicial de 100.000 bactérias.", [
 ["Que mecanismo explica o aumento da proporção de resistentes após a exposição?", "Sobrevivência diferencial favorece variantes resistentes já presentes.", ["Todas as sensíveis decidem tornar-se resistentes por necessidade.", "A substância transforma igualmente todas as variantes em resistentes.", "A resistência aparece apenas porque as resistentes são inicialmente maioria.", "A exposição elimina a hereditariedade das características bacterianas."], "O modelo informa variação hereditária anterior. A exposição seleciona sobreviventes em proporções diferentes; não é apresentada como criação dirigida da característica."],
 ["Quantas bactérias sensíveis sobrevivem sob as condições descritas?", "990", ["99.000", "1.000", "900", "9.900"], "Há 99.000 sensíveis inicialmente. Sobrevive 1% desse grupo: 990. A porcentagem deve ser aplicada às sensíveis, não à população total."],
 ["Que proporção aproximada dos sobreviventes é resistente?", "47,6%", ["1%", "90%", "99%", "9%"], "Há 900 resistentes sobreviventes e 990 sensíveis, total 1.890. A fração resistente é 900/1.890 ≈ 47,6%, maior que a inicial, embora ainda não seja maioria."],
 ["Qual conclusão é inadequada ao modelo mesmo após várias gerações sob a mesma seleção?", "A substância orientou mutações específicas em todas as bactérias sensíveis para atender à necessidade.", ["A composição da população pode mudar ao longo das gerações.", "A reprodução das sobreviventes pode ampliar a presença da variante resistente.", "A taxa de sobrevivência difere entre variantes.", "A proporção inicial não limita a proporção após a seleção."], "Seleção de variantes não equivale a mutação orientada por necessidade. As outras conclusões são compatíveis com sobrevivência diferencial e reprodução das variantes já presentes."],
 ["Qual comparação ajuda a avaliar o papel seletivo da exposição?", "Acompanhar populações inicialmente comparáveis, uma exposta e outra não exposta, registrando frequências das variantes.", ["Comparar duas populações de espécies diferentes sem medir suas frequências iniciais.", "Observar apenas a aparência das resistentes sobreviventes.", "Excluir as sensíveis dos registros antes de calcular proporções.", "Contar apenas o número total sem distinguir as variantes."], "O grupo não exposto funciona como comparação e o registro inicial permite observar mudanças de frequência. Distinguir variantes é necessário para estudar seleção, não apenas redução do total."],
]);
add("Osmose e membranas", "Três amostras iguais de células vegetais são colocadas em soluções I, II e III. A concentração externa de solutos não permeantes é, respectivamente, menor, igual e maior que a interna inicial. A membrana permite passagem de água, mas não desses solutos durante a observação. Considere a parede celular íntegra e despreze transporte ativo no período.", [
 ["Qual direção inicial do fluxo líquido de água é coerente com as três situações?", "Entrada em I, equilíbrio líquido em II e saída em III.", ["Saída em I, entrada em II e equilíbrio em III.", "Entrada em todas, porque células vegetais sempre absorvem água.", "Saída em todas, porque os solutos não atravessam.", "Equilíbrio em I, saída em II e entrada em III."], "A água tende a mover-se para o meio com maior concentração efetiva de solutos não permeantes. Assim entra em I, não apresenta fluxo líquido inicial em II e sai em III."],
 ["Qual comparação descreve a diferença entre célula vegetal e uma célula sem parede sob condições hipotônicas?", "A parede limita a expansão e permite turgor, enquanto uma célula sem parede pode romper-se.", ["A parede impede completamente a entrada de água em qualquer condição.", "A ausência de parede impede osmose.", "Células vegetais perdem obrigatoriamente água em meio hipotônico.", "A parede transforma os solutos externos em água."], "A parede resiste à expansão, levando ao aumento da pressão de turgor. Sem estrutura equivalente, a entrada excessiva de água pode causar ruptura, dependendo das condições."],
 ["Em III, o citoplasma se retrai e a membrana se afasta parcialmente da parede. Qual explicação é compatível com o enunciado?", "Perda de água por osmose em meio externo mais concentrado, com plasmólise.", ["Entrada de solutos por difusão através da parede impermeável à água.", "Produção de água por transporte ativo, desprezado no período.", "Ganho de água que aumenta o turgor e rompe a parede.", "Transformação do citoplasma em parede celular adicional."], "A maior concentração externa provoca saída de água. A retração do conteúdo celular pode afastar a membrana da parede, caracterizando plasmólise."],
 ["Se células de III forem transferidas a I antes de dano irreversível, que mudança se espera inicialmente?", "Entrada de água e recuperação do volume celular.", ["Saída adicional de água, porque a solução I é menos concentrada.", "Manutenção obrigatória da retração, independentemente do meio.", "Dissolução instantânea da parede celular.", "Conversão dos solutos internos em solutos externos sem passagem de água."], "A inversão da diferença de concentração muda a tendência do fluxo: a água entra e pode reverter a plasmólise em células viáveis. Não se presume recuperação após dano irreversível."],
 ["Que alteração impediria usar diretamente as previsões anteriores?", "Os solutos começarem a atravessar rapidamente a membrana, modificando o gradiente durante o teste.", ["Manter iguais o tamanho e o número das amostras.", "Registrar o mesmo intervalo de observação nos três grupos.", "Manter a parede celular íntegra.", "Medir as concentrações externas antes de iniciar."], "As previsões supõem solutos não permeantes no período. Se eles atravessam rapidamente, o gradiente pode mudar e a tonicidade não pode ser inferida apenas da concentração inicial."],
]);
add("Diluição e concentração", "Um frasco contém 200 mL de solução com 12 g de um soluto completamente dissolvido. Acrescenta-se água até o volume total atingir 600 mL, sem retirar ou adicionar soluto. Depois, 150 mL dessa solução homogênea são separados. Considere volumes medidos após cada etapa e ausência de reação química.", [
 ["Qual concentração em g/L resulta da diluição?", "20 g/L", ["60 g/L", "6 g/L", "80 g/L", "30 g/L"], "A massa permanece 12 g e o volume final é 0,6 L. A concentração é 12/0,6 = 20 g/L, um terço dos 60 g/L iniciais."],
 ["Que massa de soluto existe nos 150 mL separados após a diluição?", "3 g", ["12 g", "9 g", "6 g", "1,5 g"], "A alíquota de 150 mL equivale a 0,15 L. Multiplicando 20 g/L por 0,15 L, obtêm-se 3 g. A homogeneidade distribui o soluto proporcionalmente ao volume."],
 ["O que acontece com a concentração no frasco original imediatamente após retirar a alíquota homogênea?", "Permanece 20 g/L, pois massa e volume diminuem na mesma proporção.", ["Cai para 15 g/L porque o volume restante é menor.", "Aumenta para 60 g/L porque a água foi retirada primeiro.", "Permanece a massa de 12 g, embora a alíquota contenha 3 g.", "Cai a zero porque a retirada elimina todo o soluto."], "Restam 9 g em 450 mL, ou 9/0,45 = 20 g/L. Retirar uma parte homogênea reduz massa e volume proporcionalmente, sem alterar sua razão."],
 ["Se a água dos 150 mL separados for evaporada até secar, sem perda de soluto, qual massa sólida resta?", "3 g", ["12 g", "20 g", "0 g", "6 g"], "A alíquota continha 3 g de soluto. Evaporar apenas solvente concentra a amostra e, ao secar, deixa a mesma massa de soluto não volátil."],
 ["Qual procedimento aumenta a concentração sem acrescentar soluto?", "Evaporar parte da água, mantendo o soluto no recipiente.", ["Acrescentar água até dobrar o volume.", "Dividir a solução homogênea em dois frascos iguais.", "Retirar uma alíquota homogênea mantendo o restante.", "Transferir toda a solução para um frasco de maior capacidade."], "Reduzir o volume do solvente sem perder soluto aumenta a razão massa/volume. Divisão ou transferência não alteram essa razão; acrescentar água a diminui."],
]);
add("Reação química e sistema fechado", "Um frasco fechado contém 5 g de bicarbonato e 25 g de solução ácida. Ao misturá-los, forma-se gás e o recipiente permanece vedado. A balança continua marcando 30 g de conteúdo. Em outro ensaio igual, o recipiente é aberto e parte do gás escapa, deixando 28 g de conteúdo medido.", [
 ["Que interpretação concilia os dois resultados com conservação de massa?", "No frasco aberto, 2 g saíram na forma de gás; no fechado, todo o conteúdo permaneceu no sistema.", ["A reação destruiu 2 g de matéria apenas porque o frasco foi aberto.", "O gás formado não possui massa e não participa da medição.", "A reação no frasco fechado produziu massa nova para manter 30 g.", "A conservação de massa exige que todo recipiente aberto mantenha o mesmo conteúdo."], "A diferença corresponde a matéria que cruzou a fronteira do sistema aberto. No fechado, o gás também é parte do conteúdo pesado; conservação não exige massa constante em sistema com saída de matéria."],
 ["Qual massa do conteúdo é esperada no frasco fechado antes e depois da reação ideal?", "30 g em ambos os momentos", ["25 g antes e 30 g depois", "30 g antes e 28 g depois", "5 g antes e 25 g depois", "28 g antes e 30 g depois"], "As massas iniciais somam 5 + 25 = 30 g. Mantendo todos os produtos dentro do frasco e sem troca de matéria, a massa total do conteúdo permanece 30 g."],
 ["Se o recipiente aberto perder mais 1 g de gás depois da primeira medição, qual massa de conteúdo terá?", "27 g", ["29 g", "30 g", "31 g", "25 g"], "O conteúdo aberto já estava em 28 g. A saída adicional de 1 g reduz a massa medida para 27 g, sem implicar destruição da matéria que saiu."],
 ["Que característica permite distinguir a reação de uma simples mudança de estado no relato?", "A formação de novas substâncias a partir dos reagentes, e não apenas a transferência de fase.", ["Qualquer presença de gás demonstra necessariamente reação química.", "Toda mudança de massa em balança é prova suficiente de reação.", "A conservação de massa acontece apenas em mudanças físicas.", "O fato de usar um frasco fechado impede a formação de substâncias novas."], "Uma reação altera a composição das substâncias. Gás também pode aparecer por vaporização, portanto bolhas isoladas não bastam; o processo dos reagentes é relevante."],
 ["Como medir a massa total dos produtos no ensaio aberto sem perder a parcela gasosa?", "Coletar o gás que sai e somar sua massa à do material restante.", ["Pesar somente o líquido final e ignorar o gás.", "Somar a capacidade do frasco em mL à massa restante em g.", "Descontar novamente 2 g do resultado final.", "Contar as bolhas sem conhecer seu volume, composição ou massa."], "A soma do material restante com o gás coletado permite contabilizar todos os produtos. Volume de recipiente e contagem de bolhas não substituem massa em condições desconhecidas."],
]);
add("Pressão e distribuição de força", "Um bloco exerce força de 600 N sobre uma superfície horizontal. Na posição I, apoia-se em área de 0,03 m²; na II, em 0,06 m². Use pressão média = força/área e despreze irregularidades do apoio. A massa do bloco não muda ao girá-lo.", [
 ["Como as pressões médias se comparam?", "20.000 Pa em I e 10.000 Pa em II.", ["10.000 Pa em I e 20.000 Pa em II.", "18 Pa em I e 36 Pa em II.", "600 Pa nas duas posições.", "20.000 Pa nas duas posições."], "Dividindo a mesma força pelas áreas: 600/0,03 = 20.000 Pa e 600/0,06 = 10.000 Pa. Dobrar a área reduz a pressão pela metade."],
 ["Que área seria necessária para limitar a pressão média a 5.000 Pa?", "0,12 m²", ["0,03 m²", "0,06 m²", "0,3 m²", "0,012 m²"], "P = F/A implica A = F/P = 600/5.000 = 0,12 m². O limite exige área quatro vezes maior que o primeiro apoio."],
 ["Se a força aumentar para 1.200 N, mantendo o apoio II, que pressão resulta?", "20.000 Pa", ["10.000 Pa", "40.000 Pa", "72 Pa", "2.000 Pa"], "A força dobrou e a área permaneceu 0,06 m². A pressão dobra de 10.000 para 20.000 Pa, pois depende da razão entre força e área."],
 ["Que aplicação usa o mesmo princípio para reduzir pressão sobre solo pouco resistente?", "Ampliar a área de contato de um veículo, mantendo a força total comparável.", ["Reduzir a área de contato sem alterar a força.", "Dobrar a força mantendo a mesma área.", "Concentrar a força em pontas menores.", "Aumentar a força e reduzir a área ao mesmo tempo."], "A distribuição da força por uma área maior reduz a pressão média. As outras mudanças elevam a razão força/área em vez de reduzi-la."],
 ["Que limitação impede afirmar que a pressão é idêntica em todos os pontos de um apoio real?", "O cálculo usa pressão média e não incorpora irregularidades na distribuição de contato.", ["A força do bloco deixa de existir quando ele gira.", "A unidade pascal mede massa, não pressão.", "Áreas maiores sempre eliminam qualquer deformação do solo.", "A pressão média não depende das medidas de área fornecidas."], "A razão F/A fornece um valor médio. Em contato real, forças locais e irregularidades podem produzir valores distintos; o modelo não descreve cada ponto."],
]);
add("Ondas e mudança de meio", "Uma onda periódica tem frequência de 5 Hz e se propaga a 20 m/s no meio I. Ao entrar no meio II, sua velocidade passa a 10 m/s, mantendo a frequência imposta pela fonte. Use v = f × λ. Não há informação suficiente para calcular amplitudes ou energias transmitidas.", [
 ["Quais comprimentos de onda resultam nos dois meios?", "4 m no I e 2 m no II.", ["2 m no I e 4 m no II.", "100 m no I e 50 m no II.", "5 m nos dois meios.", "4 m nos dois meios."], "O comprimento é v/f. No meio I, 20/5 = 4 m; no II, 10/5 = 2 m. A frequência se mantém e a velocidade diferente altera o comprimento de onda."],
 ["Qual é o período da fonte?", "0,2 s", ["5 s", "4 s", "2 s", "0,5 s"], "Período é o intervalo de uma oscilação: T = 1/f = 1/5 = 0,2 s. Ele permanece associado à fonte nos dois meios."],
 ["Que mudança ocorre na quantidade de comprimentos de onda contidos em um trecho de 20 m após entrar em II?", "Passa de 5 para 10 comprimentos de onda.", ["Passa de 10 para 5.", "Permanece em 5 porque a frequência é igual.", "Passa de 4 para 2.", "Passa de 20 para 10."], "No meio I, 20/4 = 5 comprimentos; no II, 20/2 = 10. Frequência igual não significa espaçamento espacial igual quando a velocidade muda."],
 ["A velocidade menor em II prova que a onda perdeu metade de sua energia?", "Não; amplitude e propriedades energéticas não foram fornecidas para essa conclusão.", ["Sim; energia e velocidade sempre têm a mesma proporção em qualquer onda.", "Sim; manter frequência implica energia nula no segundo meio.", "Não; a energia necessariamente dobra quando a velocidade cai pela metade.", "Sim; comprimento de onda menor comprova ausência de transmissão."], "A relação v = fλ determina grandezas cinemáticas. Energia envolve amplitude e propriedades do meio; os dados não sustentam uma proporcionalidade universal entre energia e velocidade."],
 ["Se a fonte passar a 10 Hz no meio I, mantendo velocidade de 20 m/s, qual será o comprimento de onda?", "2 m", ["4 m", "10 m", "200 m", "0,5 m"], "Mantendo a velocidade e dobrando a frequência, o comprimento cai pela metade: 20/10 = 2 m. A alteração agora está na fonte, não no meio."],
]);
add("Estações e duração da luz", "Uma escola compara duas cidades de latitudes semelhantes em hemisférios opostos. Em dezembro, a cidade do hemisfério sul tem cerca de 14 horas de luz e a do norte, 10 horas. Em junho os valores se invertem. Considere a inclinação do eixo terrestre e a translação; não atribua as estações apenas à distância entre Terra e Sol.", [
 ["Qual explicação integra a inversão sazonal entre hemisférios?", "A inclinação do eixo modifica a incidência solar e a duração do dia ao longo da translação.", ["A Terra fica mais próxima do Sol apenas para o hemisfério sul em dezembro.", "A rotação anual inverte os hemisférios norte e sul.", "A órbita faz cada cidade mudar de hemisfério em junho.", "A inclinação do eixo deixa de existir durante o inverno."], "A orientação do eixo relativamente estável durante a translação favorece alternadamente cada hemisfério em duração do dia e incidência solar. A distância ao Sol é compartilhada pela Terra inteira."],
 ["Que diferença de tempo de luz a cidade sul apresenta entre os dois meses do exemplo?", "4 horas", ["24 horas", "2 horas", "10 horas", "14 horas"], "No exemplo, a cidade sul recebe 14 horas em dezembro e 10 em junho. A diferença é 4 horas; isso descreve a comparação fornecida, não todas as latitudes."],
 ["Que observação contradiz mais diretamente a explicação baseada só na aproximação de toda a Terra ao Sol?", "Os hemisférios apresentam estações opostas no mesmo momento.", ["O dia alterna com a noite em uma mesma cidade.", "Há nuvens em alguns dias de dezembro.", "A Terra possui continentes e oceanos.", "As cidades têm habitantes em números diferentes."], "Uma variação de distância comum ao planeta não explica sozinha favorecimento oposto dos hemisférios simultaneamente. Essa oposição é compatível com inclinação e incidência solar."],
 ["Se o eixo não tivesse inclinação, mantendo a translação, o que mudaria no mecanismo descrito?", "A alternância de iluminação associada à inclinação seria eliminada ou fortemente reduzida no modelo ideal.", ["A rotação pararia automaticamente.", "O hemisfério sul permaneceria sempre voltado ao Sol e o norte sem iluminação.", "A Terra deixaria obrigatoriamente de orbitar o Sol.", "A duração do ano passaria a ser igual à do dia."], "A inclinação é central ao mecanismo de contraste sazonal entre hemisférios. Retirá-la não implica parar rotação ou translação; são movimentos distintos."],
 ["Qual cuidado evita transformar o exemplo de horas de luz em uma regra para qualquer cidade?", "Considerar latitude, data e condições locais antes de generalizar valores de duração do dia.", ["Aplicar 14 horas a todo local do hemisfério sul durante qualquer mês.", "Usar apenas o número de habitantes para prever o tempo de luz.", "Considerar a temperatura do dia como medida direta da latitude.", "Supor que a translação altera a latitude das cidades."], "A duração do dia varia com latitude e época. Os valores ilustram duas cidades comparáveis; não representam todos os pontos dos hemisférios, especialmente regiões equatoriais e polares."],
]);
add("Respiração celular e interpretação de medidas", "Dois frascos com a mesma quantidade de sementes da mesma espécie são mantidos no escuro e na mesma temperatura. A contém sementes em germinação; B, sementes previamente inativadas. A concentração de oxigênio em A cai de 21% para 18% no período observado, enquanto B permanece em 21%. Não há renovação do ar durante o teste.", [
 ["Que inferência é compatível com a comparação entre os frascos?", "As sementes vivas em germinação consomem oxigênio, de modo compatível com respiração celular.", ["O consumo depende de fotossíntese porque o teste ocorreu no escuro.", "A inativação faz as sementes de B respirarem mais intensamente.", "A queda do oxigênio comprova que a matéria desapareceu.", "As sementes em A produzem oxigênio líquido no período."], "O grupo vivo difere do controle inativado e apresenta redução de oxigênio. Isso é compatível com metabolismo respiratório; no escuro, não se atribui a queda à produção fotossintética."],
 ["Qual redução relativa da concentração de oxigênio ocorre em A, tomando 21% como referência inicial?", "Aproximadamente 14,3% da concentração inicial.", ["3% da concentração inicial.", "18% da concentração inicial.", "21% da concentração inicial.", "Aproximadamente 85,7% da concentração inicial."], "A diferença é de 3 pontos percentuais. A redução relativa é 3/21 × 100 ≈ 14,3%; pontos percentuais e porcentagem relativa não são a mesma medida."],
 ["Por que o frasco B é relevante para a interpretação?", "Permite verificar alterações sem metabolismo das sementes, mantendo outras condições comparáveis.", ["Fornece uma previsão de oxigênio a ser produzido pelas sementes vivas.", "Elimina a necessidade de controlar temperatura e quantidade de sementes.", "Prova que todo processo respiratório exige luz.", "Garante que as duas concentrações teriam de mudar igualmente."], "O controle inativado ajuda a distinguir a mudança associada às sementes vivas de alterações do aparelho ou ambiente. Sua utilidade depende de condições comparáveis."],
 ["Que resultado adicional seria coerente com respiração aeróbia no frasco A?", "Aumento de gás carbônico associado ao metabolismo, sem afirmar proporção exata não medida.", ["Eliminação de toda produção de calor pelas sementes.", "Criação de oxigênio que substitui exatamente a quantidade consumida.", "Desaparecimento de átomos de carbono durante o processo.", "Produção de glicose exclusivamente a partir da ausência de luz."], "Na respiração aeróbia, matéria orgânica e oxigênio participam de transformações que podem liberar CO₂ e energia. Os dados não permitem calcular uma proporção precisa de gases sem outras medições."],
 ["Se A estivesse aberto e recebesse ar continuamente, que dificuldade surgiria?", "A reposição externa poderia mascarar o consumo de oxigênio pelas sementes.", ["A abertura faria cessar obrigatoriamente toda respiração.", "O oxigênio perderia sua massa ao entrar no frasco.", "A concentração inicial não dependeria mais do ar externo.", "O controle B se transformaria em produtor de oxigênio."], "Um sistema aberto troca gases; uma concentração aproximadamente constante pode coexistir com consumo reposto pelo ambiente. Por isso o fechamento é importante para a leitura inicial."],
]);
add("Eutrofização e oxigênio dissolvido", "Após receber escoamento rico em nutrientes, um lago apresenta crescimento de algas. Dias depois, parte delas morre; aumenta a atividade de decompositores e cai o oxigênio dissolvido. Em noites sem luz, a concentração chega a 2 mg/L, abaixo do valor anterior de 8 mg/L. O experimento é um cenário simplificado de eutrofização.", [
 ["Qual encadeamento explica a redução de oxigênio sem supor que nutrientes sejam venenos diretos?", "Nutrientes favorecem algas; a decomposição da biomassa e a respiração elevam o consumo de oxigênio.", ["Nutrientes transformam automaticamente todo oxigênio em sal.", "Decompositores interrompem a respiração quando recebem mais matéria orgânica.", "A morte das algas elimina toda atividade biológica no lago.", "As algas só consomem oxigênio quando há luz intensa."], "A entrada de nutrientes pode ampliar a biomassa; sua decomposição e a respiração de organismos consomem oxigênio. A falta de produção fotossintética noturna acentua o balanço negativo."],
 ["Qual é a queda percentual em relação aos 8 mg/L anteriores?", "75%", ["25%", "6%", "400%", "50%"], "A redução foi 8 − 2 = 6 mg/L. Em relação ao valor inicial, 6/8 × 100 = 75%; 25% é a fração que permaneceu."],
 ["Por que a queda pode se intensificar à noite?", "A fotossíntese dependente de luz diminui ou cessa, enquanto a respiração pode continuar.", ["Toda respiração cessa no escuro e o oxigênio deixa de existir.", "A noite transforma nutrientes em peixes consumidores.", "A ausência de luz obriga algas a liberar mais oxigênio por fotossíntese.", "O lago deixa de trocar gases com a atmosfera apenas por ser noite."], "A produção fotossintética depende de luz; o consumo respiratório não cessa necessariamente no escuro. O balanço entre produção e consumo pode, assim, reduzir a concentração noturna."],
 ["Que medida enfrenta a causa descrita, em vez de apenas aumentar oxigênio temporariamente?", "Reduzir o aporte de nutrientes por manejo de escoamento e efluentes.", ["Adicionar mais fertilizantes para substituir as algas mortas.", "Retirar toda a água sem alterar as fontes de escoamento.", "Aquecer o lago para acelerar a decomposição.", "Aumentar apenas a iluminação artificial sem controlar nutrientes."], "Controlar a entrada de nutrientes reduz a condição que iniciou o crescimento excessivo da biomassa. Intervenções somente no oxigênio não removem a fonte do processo."],
 ["Qual cuidado é necessário ao interpretar uma única medida diurna de oxigênio?", "Ela pode não revelar a queda noturna, exigindo medidas em horários diferentes.", ["Uma medida diurna permite reconstruir exatamente todas as concentrações noturnas.", "A concentração de oxigênio é fixa em um lago durante 24 horas.", "A presença de algas torna toda medida de oxigênio irrelevante.", "O horário só afeta a massa de nutrientes, não processos biológicos."], "O balanço varia com luz e atividade biológica. Medidas em horários distintos ajudam a captar ciclos e valores mínimos que uma observação diurna isolada pode ocultar."],
]);
add("Populações e limite de recursos", "Em um cultivo com espaço e alimento limitados, uma população passa de 100 para 200 indivíduos e depois para 320. No período seguinte chega a 380 e então se estabiliza perto de 400. Não houve entrada deliberada de indivíduos. O ambiente continua sendo monitorado, pois sua capacidade não é considerada imutável.", [
 ["Que leitura distingue esse crescimento de uma duplicação indefinida?", "O acréscimo diminui ao se aproximar de um limite associado a recursos e espaço.", ["A população duplica em todos os períodos observados.", "A estabilização prova ausência de nascimentos e mortes.", "O valor 400 é um limite fixo para qualquer ambiente da espécie.", "A passagem de 200 para 320 corresponde a duplicação exata."], "Os acréscimos posteriores são menores e a população se aproxima de um patamar. Isso é compatível com limitações ambientais; estabilidade do total não significa ausência de renovação."],
 ["Qual crescimento relativo ocorre de 200 para 320 indivíduos?", "60%", ["120%", "160%", "37,5%", "20%"], "O acréscimo é 120 indivíduos. Dividindo pelo valor inicial desse intervalo, 120/200 = 0,60, ou 60%. O número 320 equivale a 160% do inicial, não ao acréscimo percentual."],
 ["Que mudança pode alterar o patamar próximo de 400?", "Modificação da oferta de alimento ou do espaço disponível.", ["Manter todas as condições ambientais exatamente iguais.", "Trocar apenas o nome atribuído à população.", "Contar indivíduos em outra ordem na mesma amostra.", "Mudar a unidade de registro de indivíduos para centenas, sem mudar o ambiente."], "A capacidade de suporte depende de recursos e condições; mudanças reais nessas condições podem modificar o patamar. Uma alteração na representação dos dados não altera o ambiente."],
 ["Qual resultado pode produzir estabilidade em torno de 400 mesmo com reprodução contínua?", "Nascimentos e mortes aproximadamente equilibrados ao longo dos períodos.", ["Proibição de qualquer morte assim que o total atinge 400.", "Transformação de todos os indivíduos em organismos não reprodutivos.", "Duplicação seguida de ausência completa de mortalidade.", "Entrada de novos indivíduos sem qualquer saída ou morte."], "Um total estável pode refletir equilíbrio dinâmico de entradas e saídas. O gráfico de abundância, sozinho, não mostra os fluxos internos de nascimento e morte."],
 ["Qual informação adicional ajuda a investigar o mecanismo da desaceleração?", "Medir alimento disponível por indivíduo e taxas de nascimento e morte em cada intervalo.", ["Registrar somente a cor do recipiente de cultivo.", "Usar apenas o maior total observado como explicação suficiente.", "Ordenar os períodos por quantidade, removendo a sequência temporal.", "Comparar somente o nome científico da espécie com o número 400."], "Recursos por indivíduo e taxas demográficas podem relacionar limitação ambiental ao crescimento. Reordenar períodos ou tomar um número como causa impede essa análise."],
]);
add("Placas tectônicas e evidências", "Em uma região, terremotos se concentram numa faixa estreita. Há uma cadeia montanhosa paralela à faixa e um alinhamento de vulcões no continente. Estudos indicam que uma placa oceânica mergulha sob uma continental. Em outra região, duas placas se afastam e há formação de nova crosta junto a uma dorsal.", [
 ["Qual comparação dos limites é coerente com as evidências?", "O primeiro é convergente com subducção; o segundo é divergente com formação de crosta.", ["Ambos são divergentes, porque todo terremoto cria nova crosta.", "O primeiro é transformante, sem deslocamento vertical de placas.", "O segundo é convergente e destrói crosta em uma dorsal.", "Ambos são imóveis; o vulcanismo é independente de movimento de placas."], "O mergulho de uma placa sob outra caracteriza subducção em limite convergente. O afastamento associado a dorsais permite ascensão de material e formação de crosta oceânica."],
 ["Por que o conjunto de montanhas, vulcões e terremotos é mais informativo que um evento isolado?", "A distribuição espacial reúne evidências de um processo regional consistente com o modelo de placas.", ["Um terremoto isolado demonstra com precisão o tipo de qualquer limite.", "Montanhas e vulcões só existem no mesmo local por coincidência sem interpretação.", "A concentração em faixa elimina qualquer risco de novos eventos.", "A presença de montanhas prova que não há movimentos atuais."], "Diferentes observações espacialmente relacionadas permitem testar uma explicação comum. Um evento isolado ou uma paisagem, por si só, não caracteriza necessariamente todos os mecanismos."],
 ["Qual processo mantém aproximadamente o balanço de crosta oceânica ao longo do tempo geológico?", "Formação em dorsais e consumo em zonas de subducção.", ["Formação apenas em continentes e ausência de qualquer consumo.", "Destruição somente por terremotos rasos em desertos.", "Criação de crosta por transformação de toda água oceânica em rocha.", "Afastamento de placas sem qualquer formação de material."], "A tectônica relaciona criação de crosta nas dorsais com reciclagem de material nas zonas de subducção. O balanço geológico não exige crescimento indefinido da superfície terrestre."],
 ["Se duas placas deslizarem lateralmente uma em relação à outra, que comparação evita confundir esse limite com a dorsal?", "É um limite transformante, sem criação sistemática de crosta pelo simples deslizamento.", ["O deslizamento lateral significa sempre subducção de uma placa.", "A presença de movimento cria necessariamente uma dorsal.", "Todo limite transformante aumenta a área total da Terra.", "Placas que deslizam não podem gerar tensões ou terremotos."], "Limites transformantes têm movimento lateral relativo e podem acumular tensão sísmica. Diferem do afastamento construtivo típico das dorsais."],
 ["Que informação é insuficiente para prever dia e hora de um futuro terremoto?", "A identificação do limite e do histórico regional, embora ajude a avaliar risco.", ["Uma simulação com certeza física de cada ruptura futura, condição não fornecida.", "Conhecimento completo e verificável de toda evolução de tensão, condição não fornecida.", "Registro direto do evento após ocorrer, usado como previsão retrospectiva.", "A definição de um calendário preciso pela quantidade de vulcões, procedimento inexistente no modelo."], "Modelos e histórico permitem avaliação de risco, mas não fornecem previsão exata de data e hora de cada ruptura. As outras opções não são informações efetivamente disponíveis ou métodos válidos de previsão."],
]);
add("Materiais, condução e isolamento", "Duas caixas idênticas, com mesma quantidade de gelo e mesma temperatura inicial, são colocadas no mesmo ambiente. A é revestida de metal; B, de espuma isolante. A caixa B mantém mais gelo ao final. A espuma não produz frio; o experimento busca explicar a diferença por transferência de energia.", [
 ["Qual interpretação respeita o resultado sem atribuir criação de frio à espuma?", "A espuma reduz a transferência de calor do ambiente para o conteúdo, retardando a fusão.", ["A espuma produz energia negativa e transforma água em gelo continuamente.", "O metal impede toda transferência de energia por possuir maior massa.", "A existência de gelo elimina a influência da temperatura externa.", "A diferença comprova que a espuma remove átomos de água do conteúdo."], "Um isolante dificulta a transferência de calor. O gelo recebe menos energia por unidade de tempo e funde mais lentamente; não há produção de frio como substância."],
 ["Qual variável deve permanecer comparável para atribuir a diferença ao revestimento?", "A quantidade inicial de gelo, junto com geometria e condições de exposição.", ["A caixa A deve receber mais gelo e ficar à sombra, enquanto B fica ao sol.", "As caixas devem ter temperaturas iniciais distintas.", "Uma das caixas deve ser aberta durante todo o teste, sem registrar a diferença.", "O tamanho das caixas deve variar de acordo com o material."], "Manter quantidade, geometria e exposição comparáveis ajuda a isolar o efeito do revestimento. Mudanças simultâneas poderiam explicar o resultado por outros fatores."],
 ["Se o conteúdo estivesse quente e o ambiente frio, qual previsão sobre a espuma seria coerente?", "Ela também retardaria a perda de calor do conteúdo para o ambiente.", ["Ela aceleraria obrigatoriamente a perda porque funciona apenas com gelo.", "Ela transformaria calor em frio sem transferir energia.", "Ela eliminaria qualquer diferença de temperatura imediatamente.", "Ela faria o metal deixar de conduzir calor."], "Isolamento reduz a taxa de transferência, independentemente de qual lado está mais quente. O sentido espontâneo do fluxo acompanha a diferença de temperatura, não a existência de gelo."],
 ["Que observação impediria concluir que B não recebeu calor durante o teste?", "Mesmo em B parte do gelo derreteu, indicando entrada de energia sob as hipóteses dadas.", ["A presença de espuma prova transferência exatamente nula em qualquer intervalo.", "A quantidade maior de gelo restante comprova geração permanente de gelo novo.", "O revestimento metálico transforma temperatura em massa.", "A temperatura ambiente deixa de existir quando a caixa é fechada."], "Manter mais gelo não equivale a isolamento perfeito. A fusão de parte dele é compatível com entrada de energia, apenas mais lenta que em A."],
 ["Se os dois conteúdos forem observados por tempo suficiente no mesmo ambiente, sem fontes ativas, o que se espera em termos de tendência térmica?", "Ambos tendem ao equilíbrio com o ambiente; o isolamento altera principalmente a velocidade da aproximação.", ["B mantém necessariamente gelo para sempre porque contém espuma.", "A temperatura de A cresce sem limite por possuir metal.", "A temperatura externa é invertida pela passagem do tempo.", "O revestimento faz cada caixa produzir uma temperatura independente do ambiente."], "Sem fontes ativas, o isolamento passivo não sustenta indefinidamente uma diferença de temperatura. Ele reduz a taxa de transferência e prolonga a aproximação do equilíbrio."],
]);
export function sciences() {
  if (cases.length !== 20) throw Error("Ciências: completar vinte situações");
  return Array.from({ length: 5 }, (_, variant) => cases.map((g, index) => ({ ...g[variant], family: `C${index + 1}`, variant: variant + 1 }))).flat();
}
